# Schrijft src/data/BRONNEN.md uit de databestanden (zodat de aantallen kloppen).
import sys, json, os, collections
D = sys.argv[1]
P = json.load(open(f'{D}/places.json')); K = json.load(open(f'{D}/klanten.json')); B = json.load(open(f'{D}/buildings.json'))
R = json.load(open(f'{D}/roads_display.json')); G = json.load(open(f'{D}/graph.json')); T = json.load(open(f'{D}/toegang.json'))
nl = lambda n: f'{n:,}'.replace(',', '.')
kb = lambda f: f"{os.path.getsize(f'{D}/{f}') / 1024:,.0f} kB".replace(',', '.')
fm = collections.Counter(s['formule'] for s in K['stores'])
eil = [s for s in K['stores'] if s.get('eiland')]
so = collections.Counter(d['soort'] for d in K['dcs'])
nb = sum(len(v) for v in B.values()); nd = sum(1 for v in B.values() for b in v if b.get('d'))
L = []; w = L.append
w('# Bronnen van de data (Control Tower 4.0)')
